    "r90.a77f2d2326e3": "<span class=\"abadge\">{{svg1}}Không bao giờ có phí</span><span class=\"abadge\">{{svg2}}Một trong 300 ghế</span><span class=\"abadge\">Dự kiến xem xét bởi con người</span>",
