    "a90.3a51ce88d3a1@alt": "Bản render khái niệm của thiết bị Enki: một viên sỏi gốm cỡ lòng bàn tay màu trắng ngà với nút nguồn bằng đồng thau tròn, một đèn LED pin nhỏ, một cổng USB-C duy nhất và không có màn hình",
    "a90.4306523a0699@alt": "Bản render khái niệm của thiết bị Enki màu trắng ngà được cầm trên tay, với một điện thoại chạy ứng dụng đi kèm, kính thông minh và tai nghe trên bàn phía sau nó",
    "meta90.aa6a48227049@content": "Thiết bị Enki là một khái niệm AI cục bộ cỡ bỏ túi, chưa phải là sản phẩm. Khám phá các mục tiêu kỹ thuật, mục tiêu thiết kế mở, các ràng buộc và vai trò đề xuất của nó trong một mạng lưới gia đình.",
    "r90.cdb263af2652": "Enki — Trí tuệ thuộc về mọi người, mọi nơi",
    "r90.a13f6e8e8987": "<span class=\"hero-stat__value\">÷280</span><span class=\"hero-stat__label\">chi phí suy luận lớp GPT-3.5, tháng 11 năm 2022 → tháng 10 năm 2024</span>",
    "r90.08de2ea5b485": "<span class=\"hero-stat__value\">3.8B</span><span class=\"hero-stat__label\">Phi-3-mini: tiến bộ cụ thể theo điểm chuẩn, không tương đương phổ quát</span>",
    "r90.20e759dae0ce": "<span class=\"hero-stat__value\">20+</span><span class=\"hero-stat__label\">mô hình cục bộ đã thử nghiệm trong nghiên cứu IPW</span>",
    "r90.df10a9fbad65": "<span class=\"hero-stat__value\">300</span><span class=\"hero-stat__label\">thành viên mục tiêu, bao gồm cả người sáng lập</span>",
    "r90.9f1651d393eb": "Đọc bản tuyên ngôn <span class=\"arr\">→</span>",
    "home94.clientKicker": "03 · Máy khách",
    "home94.clientDescription": "Kết nối các ứng dụng bạn sử dụng với AI trên phần cứng bạn kiểm soát. Tích hợp đề xuất và bộ nhớ cục bộ bạn có thể mang theo giữa các máy khách.",
    "home94.clientLink": "Khám phá máy khách <span class=\"arr\">→</span>",
